import json, glob, hashlib
from collections import deque
results={}
for rf in glob.glob('*.result.json'):
    tid=rf[:-len('.result.json')]
    try:
        r=json.load(open(rf))
    except: continue
    reward=r.get('reward')
    mf=tid+'.messages.json'
    try:
        m=json.load(open(mf))
    except:
        continue
    # compute max consecutive identical tool-call fingerprint
    fps=[]
    for msg in m:
        tc=msg.get('tool_calls')
        if tc:
            for t in tc:
                fn=t.get('function',{})
                key=str(fn.get('name'))+chr(0)+json.dumps(fn.get('arguments'),sort_keys=True)
                fps.append(hashlib.sha256(key.encode()).hexdigest()[:16])
    maxrun=0; cur=0; prev=None
    for f in fps:
        if f==prev: cur+=1
        else: cur=1; prev=f
        maxrun=max(maxrun,cur)
    results[tid]=(reward,maxrun,len(fps))
# passing tasks with maxrun>=5
print('PASSING tasks (reward=1) max consecutive identical toolcall run:')
for tid,(rw,mr,n) in sorted(results.items(),key=lambda x:-x[1][1]):
    if rw==1:
        flag=' <<< HITS>=5' if mr>=5 else ''
        if mr>=3: print(f'  {tid}: reward={rw} maxrun={mr} n={n}{flag}')
print()
print('FAILING tasks with maxrun>=5:')
for tid,(rw,mr,n) in sorted(results.items(),key=lambda x:-x[1][1]):
    if rw==0 and mr>=5:
        print(f'  {tid}: reward={rw} maxrun={mr} n={n}')
